from functools import reduce

def compose_left(functions):
    return lambda x: reduce(lambda f, g: f(g), reversed(functions), x)

def curry(func, *args, **kwargs):
    if not sigs.has_varargs(func) and not sigs.has_keywords(func):
        return func
    else:
        def curried(*more_args, **more_kwargs):
            if sigs.has_varargs(func) or sigs.has_keywords(func):
                return curried
            else:
                return func(*args, *more_args, **kwargs, **more_kwargs)
        return curried

def num_required_args(func):
    import inspect
    sig = inspect.signature(func)
    return sum(1 for p in sig.parameters.values() if p.default == inspect.Parameter.empty)

def has_keywords(func):
    import inspect
    sig = inspect.signature(func)
    return any(p.kind == inspect.Parameter.KEYWORD_ONLY for p in sig.parameters.values())

def is_partial_args(func):
    return any(p.kind == inspect.Parameter.VAR_POSITIONAL for p in inspect.signature(func).parameters.values())
